var ImageModal = class extends import_obsidian2.FuzzySuggestModal {
  constructor(app, onPick) {
    super(app);
    this.onPick = onPick;
    this.setPlaceholder("Choose an image of a logic circuit\u2026");
  }
  getItems() {
    return this.app.vault.getFiles().filter((f) => /^(png|jpe?g|gif|webp)$/i.test(f.extension));
  }
  getItemText(f) {
    return f.path;
  }
  onChooseItem(f) {
    this.onPick(f);
  }
};
